641	  const without = (field: string): Record<string, unknown> => {
642	    const record = { ...text };
643	    delete record[field];
644	    return record;
645	  };
646	  return [
647	    // 顶层不是包含 idea 的对象
648	    { name: '顶层为 null', body: null },
649	    { name: '顶层为数组', body: [{ idea: text }] },
650	    { name: '顶层为普通字符串', body: JSON.stringify({ idea: text }) },
651	    { name: '顶层为数字', body: 1 },
652	    { name: '顶层没有 idea 字段（其他字段完整）', body: { saved: true, title: text.title } },
653	    // idea 是空值、数组或普通字符串等不能代表一条意见的内容
654	    { name: 'idea 为 null', body: { idea: null } },
655	    { name: 'idea 为 undefined（字段存在但无值）', body: { idea: undefined } },
656	    { name: 'idea 为数组', body: { idea: [text] } },
657	    { name: 'idea 为普通字符串', body: { idea: '返回的标题' } },
658	    { name: 'idea 为数字', body: { idea: 1 } },
659	    // idea 是对象、也带标题和正文，但标识不合法
660	    { name: 'id 为空字符串', body: { idea: { ...text, id: '' } } },
661	    { name: 'id 缺失', body: { idea: without('id') } },
662	    { name: 'id 为数字', body: { idea: { ...text, id: 1 } } },
663	    { name: 'id 为 null', body: { idea: { ...text, id: null } } },
664	    { name: 'id 为数组', body: { idea: { ...text, id: [] } } },
665	    // 标题、详细说明、使用场景、提交时间缺失或不是字符串
666	    { name: 'title 缺失', body: { idea: without('title') } },
667	    { name: 'title 为数字', body: { idea: { ...text, title: 1 } } },
668	    { name: 'title 为 null', body: { idea: { ...text, title: null } } },
669	    { name: 'description 缺失', body: { idea: without('description') } },
670	    { name: 'description 为数字', body: { idea: { ...text, description: 1 } } },
671	    { name: 'scenario 缺失（与空字符串不同）', body: { idea: without('scenario') } },
672	    { name: 'scenario 为数字', body: { idea: { ...text, scenario: 0 } } },
673	    { name: 'scenario 为 null', body: { idea: { ...text, scenario: null } } },
674	    { name: 'createdAt 缺失', body: { idea: without('createdAt') } },
675	    { name: 'createdAt 为数字', body: { idea: { ...text, createdAt: 0 } } },
676	    { name: 'createdAt 为 null', body: { idea: { ...text, createdAt: null } } },
677	  ];
