1062	// 提交提示归属：成功或失败提示只属于最近一次点击提交。用户可以在上一条请求还没返回时
1063	// 再次点击提交，更早请求迟到的任何结果都不能改动当前提示；但旧请求被服务确认保存的意见
1064	// 仍必须进入列表。下列用例精确控制两个 POST 的返回先后与结果类型。
1065	
1066	function settleGate(g: Gate, outcome: 'network-error' | 'server-reject' | 'broken-json' | 'missing-idea' | 'malformed-idea'): void {
1067	  if (outcome === 'network-error') {
1068	    g.reject(new TypeError('Failed to fetch'));
1069	  } else if (outcome === 'server-reject') {
1070	    g.resolve(jsonResponse(400, { error: '较早一次提交被拒绝' }));
1071	  } else if (outcome === 'broken-json') {
1072	    g.resolve(brokenJsonResponse(201));
1073	  } else if (outcome === 'malformed-idea') {
1074	    // 可解析的 201：标题、正文、场景都带回来了，但缺少 createdAt，记录结构仍不完整
1075	    g.resolve(jsonResponse(201, {
1076	      idea: { id: 'stale', title: '迟到的标题', description: '迟到的说明', scenario: '' },
1077	    }));
1078	  } else {
1079	    g.resolve(jsonResponse(201, { saved: true }));
1080	  }
1081	}
