1084	  { name: '网络错误', outcome: 'network-error' as const },
1085	  { name: '服务拒绝（400）', outcome: 'server-reject' as const },
1086	  { name: '201 但响应无法解析', outcome: 'broken-json' as const },
1087	  { name: '201 但内容不完整（缺 idea）', outcome: 'missing-idea' as const },
1088	  { name: '201 但意见结构异常（idea 缺 createdAt）', outcome: 'malformed-idea' as const },
1089	];
