  const secondIdea = makeIdea({ id: 'b', title: '后提交', description: '后提交的说明', scenario: '', createdAt: '2026-03-02T00:00:00.000Z' });
  h.setForm({ title: '先提交', description: '先提交的说明', scenario: '先提交的场景' });
